    // Parsing outside a macro context works via proc_macro2.
    let f: syn::ItemFn = syn::parse_str("fn f() -> i32 { 1 + 2 }").unwrap();
    assert_eq!(f.sig.ident, "f");
    assert_eq!(f.block.stmts.len(), 1);
}
